import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.owasp.encoder.Encode; // Importing OWASP Encoder for safe HTML encoding.

public class SecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        String safeOutput = Encode.forHtml(userInput); // Sanitizing user input to prevent XSS attacks.
        response.getWriter().println(safeOutput); // Safe output after encoding.
    }
}
```

In the first snippet, the servlet directly outputs user input, which is highly vulnerable to Cross-Site Scripting (XSS) attacks. The second snippet demonstrates a safer approach by using an HTML encoder to sanitize the user input before outputting it, thereby mitigating the risk of XSS attacks.

